package com.verifipay.user.service;
import com.verifipay.common.enums.UserRole; import com.verifipay.common.exception.*; import com.verifipay.company.repository.CompanyRepository; import com.verifipay.security.CurrentUserService; import com.verifipay.user.dto.*; import com.verifipay.user.entity.User; import com.verifipay.user.mapper.UserMapper; import com.verifipay.user.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class PlatformOwnerService { private final CurrentUserService current; private final CompanyRepository companies; private final UserRepository users; private final UserMapper mapper; private final PasswordEncoder encoder;
 @Transactional public UserResponse create(Long companyId, CreateOwnerRequest request){current.requireRole(UserRole.PLATFORM_ADMIN);if(users.existsByEmailIgnoreCase(request.email()))throw new BusinessException("Ya existe un usuario registrado con este correo");var company=companies.findById(companyId).orElseThrow(()->new ResourceNotFoundException("Empresa no encontrada"));try{return mapper.toResponse(users.save(User.builder().company(company).name(request.name().trim()).email(request.email().trim().toLowerCase()).password(encoder.encode(request.password())).role(UserRole.OWNER).active(true).build()));}catch(DataIntegrityViolationException ex){throw new BusinessException("La empresa ya tiene un OWNER activo");}}
}
